class Robot(val name: String) {
    fun describe(): String {
        return "Robot: $name"
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testDescribeTribot() {
        val robot = Robot("Tribot")
        Assert.assertEquals("Robot: Tribot", robot.describe())
    }

    @Test
    fun testDescribeOther() {
        val robot = Robot("Sparky")
        Assert.assertEquals("Robot: Sparky", robot.describe())
    }
}
